package com.aivle.backend.journey;
import com.aivle.backend.common.entity.BaseEntity;import com.aivle.backend.project.entity.Project;import com.aivle.backend.taskrun.domain.TaskRun;import jakarta.persistence.*;import java.time.LocalDateTime;import lombok.*;
@Entity(name="JourneyMarketingComparisonRun") @Table(name="marketing_comparison_runs") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED)
public class JourneyMarketingComparisonRun extends BaseEntity{public enum State{PENDING,RUNNING,SUCCEEDED,FAILED}@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="project_id",nullable=false)private Project project;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="concept_version_id",nullable=false)private ConceptVersion conceptVersion;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="workspace_id",nullable=false)private JourneyMarketingWorkspace workspace;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="task_run_id")private TaskRun taskRun;@Column(name="asset_version_ids_json",nullable=false,columnDefinition="TEXT")private String assetVersionIdsJson;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private State state;@Column(name="result_json",columnDefinition="TEXT")private String resultJson;@Column(length=100)private String error;private LocalDateTime completedAt;public static JourneyMarketingComparisonRun pending(Project p,ConceptVersion c,JourneyMarketingWorkspace w,String ids){JourneyMarketingComparisonRun v=new JourneyMarketingComparisonRun();v.project=p;v.conceptVersion=c;v.workspace=w;v.assetVersionIdsJson=ids;v.state=State.PENDING;return v;}public void start(TaskRun t){taskRun=t;state=State.RUNNING;resultJson=null;error=null;completedAt=null;}public void succeed(String r){state=State.SUCCEEDED;resultJson=r;error=null;completedAt=LocalDateTime.now();}public void fail(String e){state=State.FAILED;error=e;completedAt=LocalDateTime.now();}}
